#!/usr/bin/env bash
# Config file renderers. Each writes a complete file to stdout and reads its
# values from the environment, which install.sh populates from receiver.conf.
#
# Rendering to stdout rather than to a path is deliberate: it makes every
# generated file assertable from tests/test_receiver_render.py without a Pi,
# and it keeps the decision about *where* a file lands in the stage that owns
# it. Nothing here writes to stderr — stages tee stdout to a log, and a key on
# stderr would end up in it.

render_readsb() {
  cat <<EOF
# Generated by tools/receiver-install. Edits are lost on the next run —
# change /etc/boxradar/receiver.conf and re-run install.sh instead.
RECEIVER_OPTIONS="--device 0 --device-type rtlsdr --gain ${GAIN} --ppm ${PPM}"
DECODER_OPTIONS="--lat ${LAT} --lon ${LON} --max-range 450 --write-json-every 1"
NET_OPTIONS="--net --net-ri-port 30001 --net-ro-port 30002 --net-sbs-port 30003 --net-bi-port 30004,30104 --net-bo-port 30005 --net-ro-size=8192 --net-json-port=12345 --net-json-port-interval=0.5"
JSON_OPTIONS="--json-location-accuracy 2 --range-outline-hours 24 --db-file=/usr/local/share/tar1090/aircraft.csv.gz --db-file-lt"
EOF
}

# 30104 in --net-bi-port above is load-bearing: adsbexchange-mlat returns its
# results to 127.0.0.1:30104, and without that port readsb never accepts them.
# Dropping it does not fail loudly — MLAT aircraft just stop appearing.

render_adsbexchange() {
  cat <<EOF
# Generated by tools/receiver-install. See /etc/boxradar/receiver.conf.
# Where the feeder reads Beast from: readsb's --net-bo-port, set by
# 30-readsb.sh. This was rendered empty, which broke two things at once. The
# feeder itself has no source and cannot feed; and update.sh treats an empty
# INPUT as "never configured" and drops into setup.sh's whiptail wizard, which
# cannot draw through install.sh's log pipe. Both values below match the
# hand-built receiver that has been feeding from this site for years.
INPUT="127.0.0.1:30005"
REDUCE_INTERVAL="0.5"
USER="${ADSBX_USER}"
LATITUDE="${LAT}"
LONGITUDE="${LON}"
ALTITUDE="${ALT_FT}ft"
# dump978's raw port. Nothing serves it here — UAT is a US band and this is a
# UK site — but the upstream default names it anyway and the hand-built box
# has carried it harmlessly throughout. Left set rather than blank so this
# file stays diffable against what their own configure.sh would write.
UAT_INPUT="127.0.0.1:30978"
RESULTS="--results beast,connect,127.0.0.1:30104"
RESULTS2="--results basestation,listen,31003"
RESULTS3="--results beast,listen,30157"
RESULTS4="--results beast,connect,127.0.0.1:30154"
PRIVACY=""
INPUT_TYPE="dump1090"
MLATSERVER="feed.adsbexchange.com:31090"
TARGET="--net-connector feed1.adsbexchange.com,30004,beast_reduce_out,feed2.adsbexchange.com,64004"
NET_OPTIONS="--net-heartbeat 60 --net-ro-size 1280 --net-ro-interval 0.2 --net-ro-port 0 --net-sbs-port 0 --net-bi-port 30154 --net-bo-port 0 --net-ri-port 0 --write-json-every 1"
JSON_OPTIONS="--max-range 450 --json-location-accuracy 2 --range-outline-hours 24"
EOF
}

# adsb.lol is the ADSBExchange feedclient with different servers, so this
# renders nearly the same shape as render_adsbexchange above. The part that
# matters is the local port block, which upstream separated deliberately —
# their HEAD commit when this was added reads "avoid listen port overlap with
# ax scripts":
#
#                     basestation   beast listen   feeder --net-bi-port
#   adsbexchange         31003          30157             30154
#   adsb.lol             31420          31422             31421
#
# Only 30104 is shared, and that is an outbound connect into readsb's
# --net-bi-port (30-readsb.sh), which takes many clients — both MLAT clients
# returning results there is the intended arrangement, not a collision. Do not
# "tidy" these into one block: two feeders listening on one port means the
# second service fails to bind, and mlat-client's bind failure does not stop
# the feed, so it would look fine.
#
# ALTITUDE carries the "ft" suffix, as in render_adsbexchange and unlike
# fr24feed.ini — adsb.lol's configure.sh validates it as ^(-?[0-9]*)(ft|m)$
# and mlat-client reads metres when the suffix is absent, which would put the
# receiver 100m underground rather than fail.
render_adsblol() {
  cat <<EOF
# Generated by tools/receiver-install. Edits are lost on the next run —
# change /etc/boxradar/receiver.conf and re-run install.sh instead.
INPUT="127.0.0.1:30005"
REDUCE_INTERVAL="0.5"
USER="${ADSBLOL_USER}"
LATITUDE="${LAT}"
LONGITUDE="${LON}"
ALTITUDE="${ALT_FT}ft"
UAT_INPUT="127.0.0.1:30978"
RESULTS="--results beast,connect,127.0.0.1:30104"
RESULTS2="--results basestation,listen,31420"
RESULTS3="--results beast,listen,31422"
RESULTS4="--results beast,connect,127.0.0.1:31421"
PRIVACY=""
INPUT_TYPE="dump1090"
MLATSERVER="feed.adsb.lol:31090"
TARGET="--net-connector feed.adsb.lol,30004,beast_reduce_plus_out,feed2.adsb.lol,1337"
NET_OPTIONS="--net-heartbeat 60 --net-ro-size 1280 --net-ro-interval=0.05 --net-ro-interval-beast-reduce=0.12 --net-ro-port 0 --net-sbs-port 0 --net-bi-port 31421 --net-bo-port 0 --net-ri-port 0 --write-json-every 1"
JSON_OPTIONS="--max-range 450 --json-location-accuracy 2 --range-outline-hours 24"
EOF
}

# adsb.fi is the ADSBExchange feedclient a third time, but forked earlier than
# adsb.lol's copy: their scripts predate upstream's "avoid listen port overlap
# with ax scripts" commit and still ship 30157 as the beast listen port, which
# is ADSBExchange's. All three, as this project renders them:
#
#                     basestation   beast listen   feeder --net-bi-port
#   adsbexchange         31003          30157             30154
#   adsb.lol             31420          31422             31421
#   adsb.fi              31009        >>30170<<           30169
#
# 30170 is the single value here that is not what their own configure.sh
# would write; everything else is, deliberately, so the file stays diffable
# against it. 30157 could not stay: adsbexchange-mlat already listens there,
# so whichever mlat-client starts second fails to bind — and a failed results
# listener does not stop mlat-client feeding, so the box looks healthy with
# one results path silently dead. That is the same failure mode the adsb.lol
# comment above warns against, except here upstream hands it to us.
#
# 30170 rather than 30158: it sits next to adsb.fi's own 30169, so the block
# reads as theirs instead of one transposed digit away from ADSBExchange's.
#
# --uuid-file inside NET_OPTIONS is upstream's and is kept. The ADSBExchange
# and adsb.lol copies leave it out; adsb.fi's feed client identifies by uuid,
# so dropping it to "match the others" would make every rebuild register as a
# new receiver no matter what ADSBFI_UUID restores.
#
# ALTITUDE carries the "ft" suffix for the same reason as render_adsblol:
# their configure.sh validates ^(-?[0-9]*)(ft|m)$ and mlat-client reads a
# bare number as metres.
render_adsbfi() {
  cat <<EOF
# Generated by tools/receiver-install. Edits are lost on the next run —
# change /etc/boxradar/receiver.conf and re-run install.sh instead.
INPUT="127.0.0.1:30005"
REDUCE_INTERVAL="0.5"
USER="${ADSBFI_USER}"
LATITUDE="${LAT}"
LONGITUDE="${LON}"
ALTITUDE="${ALT_FT}ft"
UAT_INPUT="127.0.0.1:30978"
RESULTS="--results beast,connect,127.0.0.1:30104"
RESULTS2="--results basestation,listen,31009"
RESULTS3="--results beast,listen,30170"
RESULTS4="--results beast,connect,127.0.0.1:30169"
PRIVACY=""
INPUT_TYPE="dump1090"
MLATSERVER="feed.adsb.fi:31090"
TARGET="--net-connector feed.adsb.fi,30004,beast_reduce_plus_out,feed.adsb.fi,64004"
NET_OPTIONS="--net-heartbeat 60 --net-ro-size 1280 --net-ro-interval 0.2 --net-ro-port 0 --net-sbs-port 0 --net-bi-port 30169 --net-bo-port 0 --net-ri-port 0 --write-json-every 1 --uuid-file /usr/local/share/adsbfi/adsbfi-uuid"
JSON_OPTIONS="--max-range 450 --json-location-accuracy 2 --range-outline-hours 24"
EOF
}

# mlat-without-gps="yes" selects a position source, it does not supply one:
# it means "there is no GPS puck on this box, take the position from this
# file". Rendered without latitude/longitude/altitude, as this did until the
# live receiver was checked, FR24 accepts the ADS-B feed and reports
# mlat-started="YES" — the MLAT thread genuinely does start — while
# monitor.json quietly carries mlat-ok="NO" and mlat_problem="no-config", and
# not one MLAT contribution is ever made. It fed that way for months. Only
# mlat-ok and mlat_problem show it, which is why 60-verify.sh now reads both
# rather than feed_status alone.
#
# Whole feet, and no "ft" suffix unlike ALTITUDE in render_adsbexchange:
# fr24feed's own wizard asks for "antenna's altitude above the sea level (in
# feet)" and wants the bare number.
render_fr24() {
  cat <<EOF
# Generated by tools/receiver-install. Edits are lost on the next run —
# change /etc/boxradar/receiver.conf and re-run install.sh instead.
receiver="beast-tcp"
fr24key="${FR24_KEY}"
latitude="${LAT}"
longitude="${LON}"
altitude="${ALT_FT}"
bs="no"
raw="no"
mlat="yes"
mlat-without-gps="yes"
host="127.0.0.1:30005"
EOF
}
